/**
 * Gateway return landing. Minimal for now — becomes the full "blessing moment"
 * screen from the approved design in the frontend phase.
 */
export default async function ThankYou({ searchParams }) {
  const sp = await searchParams;
  const status = sp.status || 'unknown';
  const receipt = sp.receipt;
  const ok = status === 'success';
  return (
    <main style={{ maxWidth: 480, margin: '80px auto', padding: 24, textAlign: 'center' }}>
      <div style={{ fontSize: 56 }}>{ok ? '🪔' : '🙏'}</div>
      <h1 style={{ color: '#571617' }}>{ok ? 'Hare Krishna! Your seva has been offered.' : 'The payment did not complete.'}</h1>
      {ok && receipt ? <p>Receipt number: <b>{receipt}</b></p> : null}
      {!ok && status === 'failed' ? (
        <p>Nothing was charged. You can try again — the page will offer an alternate payment option.</p>
      ) : null}
      <p><a href="/" style={{ color: '#7A5D10' }}>← Back to sevas</a></p>
    </main>
  );
}
